package com.bytebazaar.api;import java.time.Instant;import java.util.List;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/orders") @CrossOrigin(origins={"http://localhost:3000","http://localhost:5173"}) public class OrderController{@PostMapping @ResponseStatus(HttpStatus.CREATED)public OrderReceipt create(@RequestBody CreateOrder order){return new OrderReceipt(UUID.randomUUID().toString(),"RECEIVED",Instant.now(),order.items());}public record OrderItem(long productId,int quantity){}public record CreateOrder(String email,List<OrderItem>items){}public record OrderReceipt(String orderId,String status,Instant createdAt,List<OrderItem>items){}}
